	@Test
	void benchmarkAutoPublicQueriesMatchIndependentBagsAndRecordNaturalPlans() throws Exception {
		for (boolean grouped : List.of(false, true)) {
			String query = grouped ? GROUP_QUERY : ROW_QUERY;
			String name = grouped ? "groups" : "rows";
			List<BindingSet> memory = collect(memoryRepository, query, "memory-" + name);
			List<BindingSet> actual = collect(nativeRepository, query, "native-" + name);
			capturePlans(query, name);
			assertThat(memory).containsExactlyInAnyOrderElementsOf(expected(grouped));
			assertThat(actual).containsExactlyInAnyOrderElementsOf(expected(grouped));
		}
	}

	private List<BindingSet> collect(SailRepository repository, String query, String name) throws Exception {
		List<BindingSet> rows = new ArrayList<>();
		Map<String, Object> receipt = publicReceipt("PUBLIC_BAG_EVALUATION", query);
		try {
			try (var connection = repository.getConnection(); var result = connection.prepareTupleQuery(query).evaluate()) {
				while (result.hasNext()) {
					MapBindingSet row = new MapBindingSet();
					BindingSet current = result.next();
					for (String binding : current.getBindingNames()) {
						row.addBinding(binding, detach(current.getValue(binding)));
					}
					rows.add(row);
				}
				receipt.put("publicResultExhausted", true);
			}
			receipt.put("publicResultAndConnectionCloseReturned", true);
			return rows;
		} finally {
			receipt.put("rows", records(rows));
			receipt.put("rowCount", rows.size());
			write(name + "-bag", receipt);
		}
	}

	private void capturePlans(String query, String name) throws Exception {
		for (Explanation.Level level : List.of(Explanation.Level.Optimized, Explanation.Level.Telemetry)) {
			try (var connection = nativeRepository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query).explain(level);
				String label = name + "-" + level.name().toLowerCase(java.util.Locale.ROOT);
				Files.writeString(output.resolve(label + "-plan.json"), explanation.toJson(), StandardCharsets.UTF_8);
				Map<String, Object> receipt = publicReceipt("SEPARATE_PUBLIC_" + level.name() + "_INVOCATION", query);
				List<Map<String, Object>> nodes = new ArrayList<>();
				metrics(explanation.toGenericPlanNode(), "root", nodes);
				receipt.put("nodes", nodes);
				receipt.put("selectedNativeStrategyRequired", false);
				receipt.put("interpretation", "Actual fallback/declines remain evidence. Preview, bag and Telemetry are separate calls.");
				write(label + "-receipt", receipt);
			}
		}
	}

