	private static Map<String, Object> publicReceipt(String category, String query) throws Exception {
		Map<String, Object> receipt = new LinkedHashMap<>();
		receipt.put("profile", PROFILE);
		receipt.put("category", category);
		receipt.put("querySha256", sha256(query));
		receipt.put("sourceObjectIdentity", null);
		receipt.put("nativeOwnerObjectIdentity", null);
		receipt.put("sourceOwnerLimitation", "Public APIs expose plan/source descriptions and open/close metrics when present; "
				+ "they do not expose the actual internal source/owner objects or a private lease census.");
		return receipt;
	}

	private static void metrics(GenericPlanNode node, String path, List<Map<String, Object>> result) {
		Map<String, Object> row = new LinkedHashMap<>();
		row.put("path", path);
		row.put("type", node.getType());
		row.put("outputRowsActual", node.getResultSizeActual());
		row.put("longs", node.getLongMetricsActual());
		row.put("doubles", node.getDoubleMetricsActual());
		row.put("strings", node.getStringMetricsActual());
		result.add(row);
		if (node.getPlans() != null) {
			for (int i = 0; i < node.getPlans().size(); i++) {
				metrics(node.getPlans().get(i), path + "/" + i, result);
			}
		}
	}

	private static void seed(SailRepository repository) {
		var vf = SimpleValueFactory.getInstance();
		try (var connection = repository.getConnection()) {
			connection.begin();
			for (int i = 1; i <= 4; i++) {
				IRI s = vf.createIRI(EX, "s" + i);
				connection.add(s, RDF.TYPE, vf.createIRI(EX, "Root"));
				for (int j = 1; j <= i; j++) {
					connection.add(s, vf.createIRI(EX, "p"), vf.createLiteral(j));
					connection.add(s, vf.createIRI(EX, "q"), vf.createLiteral(10 + j));
				}
			}
			connection.commit();
		}
	}

	private static List<BindingSet> expected(boolean grouped) {
		var vf = SimpleValueFactory.getInstance();
		List<BindingSet> result = new ArrayList<>();
		for (int i = 1; i <= 4; i++) {
			if (grouped) {
				result.add(new ListBindingSet(List.of("s", "n", "np", "nq"), vf.createIRI(EX, "s" + i),
						vf.createLiteral(BigInteger.valueOf(i * i)), vf.createLiteral(BigInteger.valueOf(i)),
						vf.createLiteral(BigInteger.valueOf(i))));
			} else {
				for (int p = 1; p <= i; p++) {
					for (int q = 1; q <= i; q++) {
						result.add(new ListBindingSet(List.of("s", "p", "q"), vf.createIRI(EX, "s" + i),
								vf.createLiteral(p), vf.createLiteral(10 + q)));
					}
				}
			}
		}
		return result;
	}

	private static Value detach(Value value) {
		var vf = SimpleValueFactory.getInstance();
		if (value instanceof IRI iri) {
			return vf.createIRI(iri.stringValue());
		}
		if (value instanceof Literal literal) {
			return literal.getLanguage().isPresent() ? vf.createLiteral(literal.getLabel(), literal.getLanguage().orElseThrow())
					: vf.createLiteral(literal.getLabel(), vf.createIRI(literal.getDatatype().stringValue()));
		}
		throw new AssertionError("Unexpected term or null in the qualified IRI/integer fixture: " + value);
	}

	private static List<Map<String, Object>> records(List<BindingSet> rows) {
		List<Map<String, Object>> result = new ArrayList<>();
		for (BindingSet row : rows) {
			Map<String, Object> cells = new TreeMap<>();
			for (String name : row.getBindingNames()) {
				Value value = row.getValue(name);
				if (value instanceof IRI iri) {
					cells.put(name, Map.of("kind", "IRI", "iri", iri.stringValue()));
				} else if (value instanceof Literal literal) {
					cells.put(name, Map.of("kind", "Literal", "label", literal.getLabel(), "datatype",
							literal.getDatatype().stringValue(), "language", literal.getLanguage().orElse("")));
				} else {
					throw new AssertionError("Unexpected fixture term " + value);
				}
			}
			result.add(cells);
		}
		return result;
	}

	private void configure(String property, String value) {
		previous.put(property, System.getProperty(property));
		restore(property, value);
	}

	private static void restore(String property, String value) {
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}

	private void write(String name, Map<String, Object> value) throws IOException {
		JSON.writerWithDefaultPrettyPrinter().writeValue(output.resolve(name + ".json").toFile(), value);
	}

	private static String sha256(String value) throws Exception {
		return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));
	}
